sys_script_include.script:
var GitHubIntegrationAjax = Class.create();
GitHubIntegrationAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    /**
     * Commits a ServiceNow update set to GitHub.
     * This method calls the GitHubIntegration Script Include,
     * which handles repo creation, branch creation, and file commits.
     */
    commitToGitHub: function () {
        var sysId = this.getParameter("sysparm_sys_id");
        var comments = this.getParameter("sysparm_comments");

        if (!sysId || !comments) {
            return "Error: Missing required parameters.";
        }

        // Instantiate Script Include
        var git = new GitHubIntegration();

        // Step 1: Retrieve update set name from sys_id
        var updateSetName = git.getUpdateSetName(sysId);
        if (!updateSetName) {
            return "Error: Invalid update set sys_id.";
        }

        // Step 2: Format repo name based on naming convention
        var repoName = git.formatRepoName(updateSetName);

        // Step 3: Get proper PAT for the context
        var token = git.getAuthToken(updateSetName);

        // Step 4: Ensure repo exists or create it
        if (!git.repoExists(repoName, token)) {
            var created = git.createRepo(sysId);
            if (!created) {
                return "Error: Failed to create GitHub repository.";
            }
        }

        // Step 5: Create a branch for this update set
        var branchName = "update-set-" + updateSetName.replace(/\s+/g, "-");
        var branchCreated = git.createBranch(repoName, branchName);
        if (!branchCreated) {
            return "Error: Failed to create branch " + branchName + ".";
        }

        // Step 6: Loop through update set records and commit each
        var gr = new GlideRecord("sys_update_xml");
        gr.addQuery("update_set", sysId);
        gr.query();

        var anyFailures = false;

        while (gr.next()) {
            var filePath = gr.name + ".xml";
            var fileContent = gr.payload.toString();

            var committed = git.commitFile(repoName, filePath, fileContent, token);

            if (!committed) {
                anyFailures = true;
                gs.error("Failed to commit file: " + filePath);
            } else {
                gs.info("Successfully committed: " + filePath);
            }
        }

        if (anyFailures) {
            return "Partial success: Some files failed to commit.";
        }

        return "Success: Update Set committed to GitHub.";
    },

    type: 'GitHubIntegrationAjax'
});
